function hasHangulText(value) {
  return Array.from(String(value)).some(ch => {
    const code = ch.codePointAt(0);
    return (code >= 0xAC00 && code <= 0xD7AF) ||
      (code >= 0x3130 && code <= 0x318F) ||
      (code >= 0x1100 && code <= 0x11FF);
  });
}

function getI18nText(lang, key, fallbackText) {
  const dict = TRANSLATIONS[lang] || {};
  const hasValue = Object.prototype.hasOwnProperty.call(dict, key);
  const value = hasValue ? dict[key] : undefined;

  if (!hasValue || value === undefined || value === null) {
    if (lang === "en") return "English translation pending.";
    if (lang === "ko" && fallbackText !== undefined && fallbackText !== null) return fallbackText;
    if (lang === "ko") return `번역 누락: ${key}`;

    const fallbackKo = TRANSLATIONS.ko && TRANSLATIONS.ko[key];
    if (fallbackKo !== undefined && fallbackKo !== null) return fallbackKo;

    const fallbackEn = TRANSLATIONS.en && TRANSLATIONS.en[key];
    if (fallbackEn !== undefined && fallbackEn !== null) return fallbackEn;

    return `Missing translation: ${key}`;
  }

  if (lang === "en" && hasHangulText(value)) {
    return "English translation pending.";
  }
  return value;
}

const MISSING_TRANSLATION_LABELS = {
  en: "English translation pending.",
  ja: "Japanese translation pending.",
  es: "Spanish translation pending."
};

function sanitizeMissingTranslationDom(lang, root = document.body) {
  if (!root) return;
  const replacementText = MISSING_TRANSLATION_LABELS[lang];
  if (!replacementText) return;

  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
    acceptNode(node) {
      const parent = node.parentElement;
      if (!parent || ["SCRIPT", "STYLE", "NOSCRIPT"].includes(parent.tagName)) {
        return NodeFilter.FILTER_REJECT;
      }
      return hasHangulText(node.nodeValue) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_SKIP;
    }
  });
  const nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);
  nodes.forEach(node => {
    if (node.nodeValue.trim()) node.nodeValue = replacementText;
  });
}

function sanitizeEnglishDom(root = document.body) {
  sanitizeMissingTranslationDom("en", root);
}

const ORIGINAL_CONTENT_SECTION_HTML = new Map();

function captureOriginalContentSections() {
  document.querySelectorAll(".content-section[id]").forEach(section => {
    if (!ORIGINAL_CONTENT_SECTION_HTML.has(section.id)) {
      ORIGINAL_CONTENT_SECTION_HTML.set(section.id, section.innerHTML);
    }
  });
}

function restoreContentSection(section) {
  if (!section || !section.id || !ORIGINAL_CONTENT_SECTION_HTML.has(section.id)) return;
  section.innerHTML = ORIGINAL_CONTENT_SECTION_HTML.get(section.id);
}

const LANG_LABELS = {
  ko: "🇰🇷 한국어",
  en: "🇺🇸 English",
  ja: "🇯🇵 日本語",
  es: "🇪🇸 Español"
};

const LANG_OPTION_LABELS = {
  ko: { ko: "🇰🇷 한국어", en: "🇺🇸 English", ja: "🇯🇵 日本語", es: "🇪🇸 Español" },
  en: { ko: "Korean", en: "English", ja: "Japanese", es: "Spanish" },
  ja: { ko: "韓国語", en: "英語", ja: "日本語", es: "スペイン語" },
  es: { ko: "Coreano", en: "Inglés", ja: "Japonés", es: "Español" }
};

let currentLang = "ko";
try {
  currentLang = localStorage.getItem("gencore-lang") || "ko";
} catch (e) {
  console.warn("localStorage not available", e);
}

function applyLanguage(lang) {
  captureOriginalContentSections();
  const activeSection = document.querySelector(".content-section.active");
  restoreContentSection(activeSection);

  currentLang = lang;
  try {
    localStorage.setItem("gencore-lang", lang);
  } catch (e) {
    console.warn("localStorage not available", e);
  }
  const dict = TRANSLATIONS[lang];
  document.querySelectorAll("[data-i18n]").forEach(el => {
    if (!el.hasAttribute("data-i18n-default")) {
      el.setAttribute("data-i18n-default", el.innerHTML);
    }
    const key = el.getAttribute("data-i18n");
    const fallbackText = el.getAttribute("data-i18n-default");
    const text = typeof getI18nText === "function" ? getI18nText(lang, key, fallbackText) : dict[key];
    if (text !== undefined) el.innerHTML = text;
  });
  // Update lang button label
  const btn = document.getElementById("langBtnLabel");
  if (btn) btn.textContent = LANG_LABELS[lang];
  // Mark active dropdown item
  document.querySelectorAll(".lang-dropdown button").forEach(b => {
    b.classList.toggle("active", b.dataset.lang === lang);
    const labels = LANG_OPTION_LABELS[lang];
    if (labels && labels[b.dataset.lang]) b.textContent = labels[b.dataset.lang];
  });
  document.documentElement.lang = lang;
  document.documentElement.dataset.lang = lang;

  // Re-render the active section to update its dynamic content
  if (activeSection && typeof renderSection === "function") {
    renderSection(activeSection.id);
  } else if (lang !== "ko" && activeSection) {
    sanitizeMissingTranslationDom(lang, activeSection);
  }
}
